/* ПЛАГИН «ГИПЕРИОН»
   Работает с Planning по REST. В 11.1.2.4 он есть, но путь версии другой:
   не /rest/v3, как в облаке, а /rest/11.1.2.4. Поэтому версия — параметр,
   а команда «Определить версию» спрашивает её у самого сервера:
   GET /HyperionPlanning/rest/ возвращает список доступных.

   Про вход: на многих установках 11.1.2.4 логин нужно писать вместе с
   доменом — «домен.пользователь», иначе сервер отвечает 401.

   Essbase напрямую в 11.1.2.4 REST не умеет — там JAPI и SOAP. Читать кубы
   можно через APS по XMLA либо через связного на своей стороне.        */

const БАЗА = '/HyperionPlanning/rest';

function общие(){
  return параметры({
    сервер:      {тип:'текст', имя:'Адрес сервера', умолчание:'http://127.0.0.1:8931'},
    версия:      {тип:'список', имя:'Версия REST',
                  значения:['11.1.2.4','11.1.2.3.600','v3','v2','v1'], умолчание:'11.1.2.4'},
    приложение:  {тип:'текст', имя:'Приложение',     умолчание:'Vision'},
    куб:         {тип:'текст', имя:'План или куб',   умолчание:'Plan1'},
    пользователь:{тип:'текст', имя:'Пользователь (домен.имя)', умолчание:''},
    пароль:      {тип:'текст', имя:'Пароль',         умолчание:''},
  });
}
const корень = п => String(п.сервер).replace(/\/+$/, '') + БАЗА;
function адрес(п, хвост){
  return корень(п) + '/' + п.версия
    + хвост.replace('{app}', encodeURIComponent(п.приложение))
           .replace('{cube}', encodeURIComponent(п.куб));
}
/* btoa понимает только latin1, а логин и пароль бывают кириллицей. */
function вБазу64(s){
  const b = new TextEncoder().encode(s);
  let bin = '';
  for(let i = 0; i < b.length; i++) bin += String.fromCharCode(b[i]);
  return btoa(bin);
}
function заголовки(п){
  const h = {'Content-Type': 'application/json'};
  if(п.пользователь) h['Authorization'] = 'Basic ' + вБазу64(п.пользователь + ':' + п.пароль);
  return h;
}
async function взять(п, url, метод, тело){
  const r = await запрос(url, {метод: метод || 'GET', заголовки: заголовки(п),
                               тело: тело ? JSON.stringify(тело) : undefined});
  if(r.код === 401)
    throw new Error('401: сервер не принял вход. В 11.1.2.4 логин часто нужен '
      + 'вместе с доменом — «домен.имя».');
  if(!r.ок) throw new Error('Сервер ответил ' + r.код + ': ' + String(r.текст || '').slice(0, 200));
  return r.тело;
}

/* Версию не угадываем и не берём из поля «version»: там лежит НАЗВАНИЕ
   («v3»), а в адресе нужен КАНОНИЧЕСКИЙ путь («11.1.2.4») — это разные
   вещи, и на этом легко построить неработающий адрес. Берём последний
   кусок из canonical-ссылки, а не сам адрес целиком: сервер называет себя
   своим внутренним именем, которое снаружи может не открываться. */
const хвостАдреса = a => {
  let t = String(a || '');
  while(t.length && t[t.length - 1] === '/') t = t.slice(0, -1);
  return t.split('/').pop();
};
function путьВерсии(d){
  const общая = ((d && d.links) || []).find(l => l.rel === 'current');
  if(общая && общая.href) return хвостАдреса(общая.href);
  const items = (d && d.items) || [];
  const последняя = items.find(x => x.isLatest) || items[items.length - 1];
  const кан = ((последняя && последняя.links) || []).find(l => l.rel === 'canonical');
  if(кан && кан.href) return хвостАдреса(кан.href);
  return последняя ? последняя.version : null;
}
async function ОпределитьВерсию(){
  const п = общие();
  const d = await взять(п, корень(п) + '/');
  const items = (d && d.items) || [];
  ячейка(1, 1).значение = 'Название';
  ячейка(1, 2).значение = 'Путь в адресе';
  ячейка(1, 3).значение = 'Состояние';
  ячейка(1, 4).значение = 'Последняя';
  items.forEach((x, i) => {
    const кан = ((x.links) || []).find(l => l.rel === 'canonical');
    ячейка(2 + i, 1).значение = x.version;
    ячейка(2 + i, 2).значение = кан ? хвостАдреса(кан.href) : '';
    ячейка(2 + i, 3).значение = x.lifecycle || '';
    ячейка(2 + i, 4).значение = x.isLatest ? 'да' : '';
  });
  const путь = путьВерсии(d);
  сообщить('Версий доступно: ' + items.length);
  if(путь){
    панель.поле('версия', путь);
    панель.сообщение('Версия в адресе: ' + путь + ' — подставил в поле');
    сообщить('В адресе используется «' + путь + '». Обратите внимание: название '
      + 'версии и путь у Гипериона различаются.');
  } else сообщить('Не понял ответ сервера про версии');
}

/* --- разведка -----------------------------------------------------------
   Что именно умеет конкретный сервер, надёжнее спросить у него, чем брать
   из документации: у 11.1.2.4 часть путей облачные и попросту отсутствует.
   Команда обходит вероятные адреса, показывает коды ответов и — главное —
   выписывает ссылки, которые сервер сам про себя сообщает.               */
/* На 11.1.2.4 многое делается не отдельными путями, а заданиями: выгрузка и
   загрузка данных, обновление куба, правила. Поэтому команда общая — тип и
   имя задаются в панели. */
async function ВыполнитьЗадание(){
  const п = общие();
  const тип = п.типЗадания || 'RULES';
  const имя = п.имяЗадания;
  if(!имя) throw new Error('Не указано имя задания');
  const пар = {};
  String(п.парЗадания || '').split(';').forEach(к => {
    const i = к.indexOf('=');
    if(i > 0) пар[к.slice(0, i).trim()] = к.slice(i + 1).trim();
  });
  const d = await взять(п, адрес(п, '/applications/{app}/jobs'), 'POST',
    {jobType: тип, jobName: имя, parameters: пар});
  const id = d && (d.jobId || d.jobID || d.id);
  сообщить('Задание «' + имя + '» (' + тип + ') запущено, номер ' + id);
  панель.сообщение('Задание запущено: ' + имя);
  for(let i = 0; i < 60; i++){
    const st = await взять(п, адрес(п, '/applications/{app}/jobs') + '/' + id);
    const s2 = st && (st.status != null ? st.status : st.descriptiveStatus);
    if(s2 === -1 || s2 === 'Processing' || s2 === 'RUNNING'){
      await new Promise(r => setTimeout(r, 2000));
      continue;
    }
    сообщить('Готово: ' + (st.descriptiveStatus || s2));
    панель.сообщение('Задание завершено: ' + (st.descriptiveStatus || s2));
    return;
  }
  сообщить('Задание ещё считается — проверьте номер ' + id + ' позже.');
}
async function РазведатьAPI(){
  const п = общие();
  const кандидаты = [
    ['/applications', 'список приложений'],
    ['/applications/{app}', 'приложение'],
    ['/applications/{app}/forms', 'формы'],
    ['/applications/{app}/dataforms', 'формы (другое имя)'],
    ['/applications/{app}/formfolders', 'папки форм'],
    ['/applications/{app}/dimensions', 'измерения'],
    ['/applications/{app}/plantypes', 'планы'],
    ['/applications/{app}/plantypes/{cube}', 'план'],
    ['/applications/{app}/jobs', 'задания'],
    ['/applications/{app}/jobdefinitions', 'описания заданий'],
    ['/applications/{app}/substitutionvariables', 'подстановочные переменные'],
    ['/applications/{app}/planningunits', 'единицы согласования'],
    ['/applications/{app}/datasources', 'источники данных'],
    ['/applications/{app}/plantypes/{cube}/exportdataslice', 'выгрузка среза'],
    ['/applications/{app}/plantypes/{cube}/importdataslice', 'загрузка среза'],
    ['/applications/{app}/dimensions/Entity/members', 'элементы измерения'],
  ];
  ячейка(1, 1).значение = 'Путь';
  ячейка(1, 2).значение = 'Код';
  ячейка(1, 3).значение = 'Что это';
  ячейка(1, 4).значение = 'Вывод';
  ячейка(1, 5).значение = 'Ссылки, которые сервер сообщает о себе';
  ячейка(1, 6).значение = 'Адрес, по которому спрашивали';
  let есть = 0;
  for(let i = 0; i < кандидаты.length; i++){
    const [хвост, что] = кандидаты[i];
    let код = '—', ссылки = '', вывод = '';
    try {
      const r = await запрос(адрес(п, хвост), {метод: 'GET', заголовки: заголовки(п)});
      код = r.код;
      /* 405 важнее 200: он значит «путь есть, но метод другой». Для выгрузки
         среза это как раз ожидаемо — она делается через POST. Считать 405
         отсутствием пути было бы ошибкой. */
      if(r.ок){
        есть++;
        вывод = 'есть';
        const l = (r.тело && r.тело.links) || [];
        ссылки = l.map(x => (x.href || '') + (x.action ? ' [' + x.action + ']' : '')).join('  ');
        if(!ссылки && r.тело) ссылки = Object.keys(r.тело).slice(0, 8).join(', ');
      } else if(r.код === 405){ есть++; вывод = 'есть, но через POST'; }
      else if(r.код === 404) вывод = 'на этой версии нет';
      else if(r.код === 401 || r.код === 403) вывод = 'нет доступа под этим входом';
      else вывод = 'ответ ' + r.код;
    } catch(e){ код = 'ошибка'; вывод = String(e.message).slice(0, 80); }
    ячейка(2 + i, 1).значение = хвост;
    ячейка(2 + i, 2).значение = код;
    ячейка(2 + i, 3).значение = что;
    ячейка(2 + i, 4).значение = вывод;
    ячейка(2 + i, 5).значение = ссылки;
    ячейка(2 + i, 6).значение = адрес(п, хвост);   // подставленный, а не шаблон
  }
  сообщить('Проверено адресов: ' + кандидаты.length + ', отвечают: ' + есть);
  панель.сообщение('Разведка окончена: отвечают ' + есть + ' из ' + кандидаты.length);
  сообщить('200 — путь есть. 405 — путь есть, но работает через POST.');
  сообщить('404 — на этой версии такого пути нет.');
  сообщить('Столбец «Ссылки» — это то, что сервер сам о себе сообщает: по ним видно,');
  сообщить('какие ещё адреса он поддерживает, даже если их нет в списке проверки.');
}

/* Всё, что нажимается в панели, получает её поля готовыми: окно параметров
   тут не нужно. параметры() как раз и вернёт присланные значения. */
async function Подключиться(){
  const п = общие();
  const d = await взять(п, адрес(п, '/applications'));
  const все = (d && (d.items || d.applications)) || [];
  const список = все.map(x => x.name || x);
  панель.список('приложения', список);
  панель.сообщение('Подключено. Приложений: ' + список.length);
  все.slice(0, 30).forEach(x => сообщить('· ' + (x.name || x)
    + (x.type ? ' (' + x.type + ')' : '')));
  if(список.length === 1) панель.поле('приложение', список[0]);
}
async function ВыбратьПриложение(){
  const п = общие();
  панель.поле('приложение', п.приложения || п.выбор);
  панель.сообщение('Приложение: ' + (п.приложения || п.выбор));
}
async function СписокИзмерений(){
  const п = общие();
  const d = await взять(п, адрес(п, '/applications/{app}/dimensions'));
  const изм = ((d && (d.items || d.dimensions)) || []).map(x => x.name || x);
  панель.дерево('измерения', изм.map(x => ({имя: x, путь: ''})));
  панель.сообщение('Измерений: ' + изм.length);
}
async function ЭлементыИзмерения(){
  const п = общие();
  const имя = п.измерения || п.выбор;
  if(!имя) throw new Error('Не выбрано измерение');
  const d = await взять(п, адрес(п, '/applications/{app}/dimensions/')
    + encodeURIComponent(имя) + '/members');
  const эл = ((d && (d.items || d.members)) || []).map(x => x.name || x);
  ячейка(1, 1).значение = имя;
  эл.forEach((м, i) => { ячейка(2 + i, 1).значение = м; });
  панель.сообщение('Элементов «' + имя + '»: ' + эл.length + ' — выписаны на лист');
}
async function ПроверитьСвязь(){
  const п = общие();
  const d = await взять(п, адрес(п, '/applications'));
  const список = ((d && (d.items || d.applications)) || []).map(x => x.name || x);
  сообщить('Связь есть. Приложений: ' + список.length);
  сообщить(список.slice(0, 20).join(', '));
}

async function ЗагрузитьСрез(){
  const п = общие();
  const d = await взять(п, адрес(п, '/applications/{app}/plantypes/{cube}/exportdataslice'),
    'POST', {exportPlanningData: false,
             gridDefinition: {suppressMissingBlocks: true, pov: [], columns: [], rows: []}});
  const сетка = (d && (d.rows || (d.gridDefinition && d.gridDefinition.rows))) || [];
  if(!сетка.length){ сообщить('Сервер вернул пустой срез'); return; }
  const заг = (d.columns || []).map(c => Array.isArray(c.headers) ? c.headers.join(' / ') : String(c));
  лист().записатьСтроку(1, ['Строка'].concat(заг));
  for(let i = 0; i < сетка.length; i++)
    лист().записатьСтроку(2 + i,
      [(сетка[i].headers || []).join(' / ')].concat(сетка[i].data || []));
  сообщить('Загружено строк: ' + сетка.length);
}

async function ОтправитьИзменения(){
  const п = общие();
  const строк = лист().строк, столбцов = лист().столбцов;
  const строки = [];
  for(let r = 2; r <= строк; r++){
    const подпись = ячейка(r, 1).значение;
    if(!подпись) continue;
    const данные = [];
    for(let c = 2; c <= столбцов; c++) данные.push(ячейка(r, c).значение);
    строки.push({headers: String(подпись).split(' / '), data: данные});
  }
  if(!строки.length){ сообщить('На листе нечего отправлять'); return; }
  const d = await взять(п, адрес(п, '/applications/{app}/plantypes/{cube}/importdataslice'),
    'POST', {aggregateEssbaseData: false, gridDefinition: {rows: строки}});
  сообщить('Отправлено строк: ' + строки.length);
  сообщить('Ответ: ' + JSON.stringify(d).slice(0, 200));
}

async function СписокФорм(){
  const п = общие();
  let d;
  try {
    d = await взять(п, адрес(п, '/applications/{app}/forms'));
  } catch(e){
    /* 404 на форме — не поломка плагина, а свойство сервера: на 11.1.2.4
       этого пути в REST просто нет. Красный крест тут вводил бы в
       заблуждение — человек решил бы, что сломалось у нас. */
    if(/ 404/.test(e.message)){
      /* Команда не сделала того, о чём просили, — значит это неудача, и
         молчать нельзя. Но текст должен объяснять и советовать, а не
         показывать голый код ответа. */
      панель.сообщение('Формы по адресу /forms этот сервер не отдаёт');
      throw new Error('Этот сервер не отдаёт формы по адресу /applications/{app}/forms '
        + '(404). Так и есть на Planning 11.1.2.4: списка форм в его REST нет. '
        + 'Нажмите «Разведать пути» — команда переберёт вероятные адреса и покажет, '
        + 'что на нём всё-таки есть. Срез можно строить и без формы: '
        + '«Построить свой» в разделе «Отчёт».');
    }
    throw e;
  }
  const формы = (d && (d.items || d.forms)) || [];
  // папки строит панель — ей нужны имя и путь
  панель.дерево('формы', формы.map(f => typeof f === 'string'
    ? {имя: f, путь: ''}
    : {имя: f.name || f.имя, путь: f.path || f.folder || ''}));
  панель.сообщение('Форм получено: ' + формы.length);
  сообщить('Форм получено: ' + формы.length);
}

/* --- ПРОИЗВОЛЬНЫЙ ОТЧЁТ ------------------------------------------------
   Главное решение: источник правды — САМА СЕТКА НА ЛИСТЕ, а не спрятанное
   описание. При обновлении элементы перечитываются из клеток. Поэтому всё
   работает само собой: удалили строку обычными средствами таблицы —
   она уйдёт из запроса; вписали новый элемент руками или скопировали —
   он попадёт в следующий срез. Ровно так ведёт себя Smart View.

   На листе память хранит только разметку: где начинается сетка и сколько
   измерений по строкам и столбцам. Сами элементы там не дублируются —
   иначе они разошлись бы с тем, что видно.                              */

const РАЗМЕТКА = 'гиперион';

/* Разметку пишем ОБЫЧНОЙ записью по клеткам, а не быстрой строчной: быстрая
   нарочно не запоминает записанное, и обновление сразу после раскладки не
   увидело бы собственной сетки. Разметка небольшая, память тут ни при чём. */
function записатьОтчёт(п, фильтры, строкиИзм, столбцыИзм, строки, столбцы){
  const nR = строкиИзм.length, nC = столбцыИзм.length;
  ячейка(1, 1).значение = 'Фильтры';
  фильтры.forEach((ф, i) => {
    ячейка(2 + i, 1).значение = ф.измерение;
    ячейка(2 + i, 2).значение = ф.элемент;
  });
  const шапка = 2 + фильтры.length + 1;          // пустая строка между блоками
  // по строке на каждое столбцовое измерение — это и есть кортежи
  for(let k = 0; k < nC; k++){
    ячейка(шапка + k, 1).значение = столбцыИзм[k];
    столбцы.forEach((t, j) => { ячейка(шапка + k, 1 + nR + j).значение = t[k]; });
  }
  строкиИзм.forEach((имя, k) => { ячейка(шапка + nC, 1 + k).значение = имя; });
  const данные = шапка + nC + 1;
  строки.forEach((t, i) => t.forEach((м, k) => { ячейка(данные + i, 1 + k).значение = м; }));
  const р = {
    сервер: п.сервер, версия: п.версия, приложение: п.приложение, куб: п.куб,
    форма: п.форма || '', пользователь: п.пользователь, пароль: п.пароль,
    фильтровСтрок: фильтры.length,
    шапка: шапка, строкИзм: nR, столбИзм: nC, данные: данные,
  };
  лист().запомнить(РАЗМЕТКА, р);
  /* Разметка для приложения: где измерения, где числа и какое измерение в
     каком столбце боковика и в какой строке шапки. По ней приложение само
     закроет измерения от правки и отдаст двойной щелчок сюда, в «Раскрыть»,
     уже посчитав точку просмотра клетки. */
  лист().разметка({
    боковик: бук(1) + (данные) + ':' + бук(nR) + (данные + Math.max(строки.length, 1) - 1),
    шапка:   бук(1 + nR) + шапка + ':' + бук(nR + Math.max(столбцы.length, 1)) + (шапка + nC - 1),
    данные:  бук(1 + nR) + данные + ':' + бук(nR + Math.max(столбцы.length, 1)) + (данные + Math.max(строки.length, 1) - 1),
    осиСтрок: строкиИзм, осиСтолбцов: столбцыИзм,
    закрыто: true,
  });
  return {
    р, фильтры, строкиИзм, столбцыИзм,
    столбцы: столбцы.map((t, j) => ({t, c: 1 + nR + j})),
    строки: строки.map((t, i) => ({t, r: данные + i})),
  };
}

/* Прочитать сетку с листа: фильтры, кортежи столбцов, кортежи строк. */
function прочитатьОтчёт(){
  const р = лист().память(РАЗМЕТКА);
  if(!р) throw new Error('На этом листе нет отчёта — сначала откройте форму или срез');
  const фильтры = [];
  for(let i = 0; i < р.фильтровСтрок; i++){
    const изм = ячейка(2 + i, 1).значение, эл = ячейка(2 + i, 2).значение;
    if(изм) фильтры.push({измерение: String(изм), элемент: эл == null ? '' : String(эл)});
  }
  const столбцыИзм = [], строкиИзм = [];
  for(let k = 0; k < р.столбИзм; k++)
    столбцыИзм.push(String(ячейка(р.шапка + k, 1).значение || ('Измерение ' + (k + 1))));
  for(let k = 0; k < р.строкИзм; k++)
    строкиИзм.push(String(ячейка(р.шапка + р.столбИзм, 1 + k).значение || ''));
  // столбцы идут вправо, пока в ПЕРВОЙ строке шапки что-то есть
  const столбцы = [];
  for(let c = 1 + р.строкИзм; ; c++){
    const первый = ячейка(р.шапка, c).значение;
    if(первый == null || первый === '') break;
    const t = [];
    for(let k = 0; k < р.столбИзм; k++){
      const v = ячейка(р.шапка + k, c).значение;
      t.push(v == null ? t[k - 1] || '' : String(v));   // пусто = как в предыдущем столбце
    }
    столбцы.push({t, c});
  }
  // строки идут вниз, пока в ПЕРВОМ столбце что-то есть
  const строки = [];
  for(let r = р.данные; ; r++){
    const первый = ячейка(r, 1).значение;
    if(первый == null || первый === '') break;
    const t = [];
    for(let k = 0; k < р.строкИзм; k++){
      const v = ячейка(r, 1 + k).значение;
      t.push(v == null ? t[k - 1] || '' : String(v));
    }
    строки.push({t, r});
  }
  return {р, фильтры, строкиИзм, столбцыИзм, строки, столбцы};
}

function срезИзСетки(g){
  return {
    pov: g.фильтры.map(ф => ({dimName: ф.измерение, members: [ф.элемент]})),
    columns: g.столбцы.map(x => ({headers: x.t})),
    rows: g.строки.map(x => ({headers: x.t})),
    rowDimensions: g.строкиИзм,
    columnDimensions: g.столбцыИзм,
  };
}

