/* Обновление: сетка читается С ЛИСТА, поэтому руками поправленные элементы
   подхватываются сами. */
async function Обновить(готовая){
  // Сетку берём с листа — кроме случая, когда её только что разложили и
  // она ещё есть в памяти этого же запуска.
  const g = готовая || прочитатьОтчёт();
  const п = g.р;
  if(!п.пользователь){
    const вход = параметры({
      пользователь:{тип:'текст', имя:'Пользователь (домен.имя)', умолчание:''},
      пароль:      {тип:'текст', имя:'Пароль', умолчание:''},
    });
    п.пользователь = вход.пользователь; п.пароль = вход.пароль;
  }
  const d = await взять(п, адрес(п, '/applications/{app}/plantypes/{cube}/exportdataslice'),
    'POST', {exportPlanningData: false, gridDefinition: срезИзСетки(g)});
  const строки = (d && (d.rows || (d.gridDefinition && d.gridDefinition.rows))) || [];
  for(let i = 0; i < g.строки.length; i++){
    const данные = (строки[i] && строки[i].data) || [];
    данные.forEach((v, j) => { ячейка(g.строки[i].r, 1 + g.р.строкИзм + j).значение = v; });
  }
  сообщить('Обновлено: строк ' + g.строки.length + ', столбцов ' + g.столбцы.length);
  if(строки.length !== g.строки.length)
    сообщить('Сервер вернул ' + строки.length + ' строк — сетка и ответ разошлись, проверьте элементы.');
}

