/* --- раскрытие члена измерения -------------------------------------------
   Двойной щелчок по клетке боковика или шапки приходит сюда. Приложение уже
   посчитало, какое это измерение, какой уровень и какой у клетки кортеж.

   РОДИТЕЛЬ ОСТАЁТСЯ, дети добавляются РЯДОМ по своей оси:

     измерение в ШАПКЕ   -> + столбцы справа от родителя, та же строка шапки
         | 1 квартал | Январь | Февраль | Март | 2 квартал |

     измерение в БОКОВИКЕ -> + строки под родителем, тот же столбец
         Москва | 1 квартал
                | Январь
                | Февраль
                | Март
                | 2 квартал

   Ни нового уровня, ни замещения: родитель виден вместе с детьми, как
   «включать выделенное» в Smart View. Свёртка убирает ровно эти клетки.  */
async function Раскрыть(){
  const повод = книга.повод;
  if(!повод) return;
  const имяИзм = повод.измерение;
  const член = повод.значение == null ? '' : String(повод.значение);
  if(!имяИзм || !член){ панель.сообщение('Не понял, какое измерение раскрывать.'); return; }
  if(повод.область !== 'боковик' && повод.область !== 'шапка'){
    панель.сообщение('Раскрывать можно измерения — боковик или шапку.');
    return;
  }

  const п = г_(прочитатьОтчёт());
  const дети = await ДетиЧлена(п, имяИзм, член);
  if(!дети.length){
    панель.сообщение('У «' + член + '» нет детей — это лист иерархии.');
    return;
  }
  /* Двойной щелчок — переключатель. Своих детей узнаём по СПИСКУ С СЕРВЕРА,
     а не по виду листа: так свёртка работает и на верхнем уровне, где
     пустых уровней над детьми просто нет, и не заглатывает брата. */
  if(УбратьДетей(повод, дети, п)){
    сообщить('Свёрнут «' + член + '»');
    панель.сообщение('Свёрнут «' + член + '».');
    await Обновить();
    return;
  }

  РаскрытьОдин(повод, дети, п);
  сообщить('Раскрыт «' + член + '» (' + имяИзм + '): детей ' + дети.length);
  панель.сообщение('Раскрыт «' + член + '» по ' + повод.область + ': ' + дети.join(', '));
  await Обновить();
}

/* Одна ступень: дети встают РЯДОМ с родителем, родитель остаётся. */
function РаскрытьОдин(повод, дети, п){
  const уровень = повод.уровень || 0;
  if(повод.область === 'боковик'){
    const r0 = повод.строка, nR = п.строкИзм;
    лист().вставитьСтроки(r0 + 1, дети.length);
    дети.forEach(function(имяРебёнка, i){
      const r = r0 + 1 + i;
      for(let k = 0; k < nR; k++)
        ячейка(r, 1 + k).значение = k === уровень ? имяРебёнка : null;
    });
    return;
  }
  const c0 = повод.столбец, nC = п.столбИзм, шапка = п.шапка;
  лист().вставитьСтолбцы(c0 + 1, дети.length);
  дети.forEach(function(имяРебёнка, i){
    const c = c0 + 1 + i;
    for(let k = 0; k < nC; k++)
      ячейка(шапка + k, c).значение = k === уровень ? имяРебёнка : null;
  });
}

/* --- свёртка -------------------------------------------------------------
   Убираем клетки, СОСЕДНИЕ с родителем, значения которых есть в списке его
   детей. Список берём у сервера, а не с листа: своей истории раскрытий не
   ведём нарочно — отчёт могли править руками, сохранить и открыть заново,
   и запомненная история к этому моменту врала бы.

   Сверка со списком заодно решает то, чего не решает вид листа: на верхнем
   уровне у детей нет пустых уровней сверху, и отличить их от брата иначе
   нечем. Здесь брат просто не попадёт в список детей.

   Возвращает true, если было что убирать.                                */
function УбратьДетей(повод, дети, п){
  const уровень = повод.уровень || 0;
  const набор = Object.create(null);
  for(const d of дети) набор[String(d)] = true;
  const пусто = v => v == null || v === '';

  if(повод.область === 'боковик'){
    const r0 = повод.строка;
    let n = 0;
    while(n < 10000){
      const v = ячейка(r0 + 1 + n, 1 + уровень).значение;
      if(пусто(v) || !набор[String(v)]) break;
      n++;
    }
    if(!n) return false;
    лист().удалитьСтроки(r0 + 1, n);
    return true;
  }
  const c0 = повод.столбец, шапка = п.шапка;
  let n = 0;
  while(n < 10000){
    const v = ячейка(шапка + уровень, c0 + 1 + n).значение;
    if(пусто(v) || !набор[String(v)]) break;
    n++;
  }
  if(!n) return false;
  лист().удалитьСтолбцы(c0 + 1, n);
  return true;
}

/* --- пункты меню клетки -------------------------------------------------- */

async function СвернутьПункт(){
  const повод = книга.повод;
  if(!повод) return;
  if(повод.область !== 'боковик' && повод.область !== 'шапка'){
    панель.сообщение('Сворачивать можно измерения — боковик или шапку.');
    return;
  }
  const п = г_(прочитатьОтчёт());
  const дети = await ДетиЧлена(п, повод.измерение, String(повод.значение || ''));
  if(!дети.length){ панель.сообщение('У «' + повод.значение + '» нет детей.'); return; }
  if(УбратьДетей(повод, дети, п)){
    панель.сообщение('Свёрнут «' + повод.значение + '».');
    await Обновить();
  } else панель.сообщение('Под «' + повод.значение + '» ничего не раскрыто.');
}

/* Вверх по иерархии: сворачиваем РОДИТЕЛЯ щёлкнутой клетки. Он остался на
   листе — раскрытие его не замещает, — поэтому просто ищем его выше (левее)
   на том же уровне и сворачиваем. */
async function УровеньВыше(){
  const повод = книга.повод;
  if(!повод || (повод.область !== 'боковик' && повод.область !== 'шапка')){
    панель.сообщение('«Уровень выше» работает по измерениям.');
    return;
  }
  const п = г_(прочитатьОтчёт());
  const уровень = повод.уровень || 0;
  const мой = String(повод.значение || '');
  /* Родитель — ближайший сосед выше (левее) на ТОМ ЖЕ уровне, у которого
     мы есть в списке детей. Так обходимся без иерархии на клиенте. */
  const шаг = повод.область === 'боковик' ? -1 : -1;
  let найден = null;
  for(let d = 1; d <= 500 && !найден; d++){
    const v = повод.область === 'боковик'
      ? ячейка(повод.строка + шаг * d, 1 + уровень).значение
      : ячейка(п.шапка + уровень, повод.столбец + шаг * d).значение;
    if(v == null || v === '') continue;
    const кандидаты = await ДетиЧлена(п, повод.измерение, String(v));
    if(кандидаты.indexOf(мой) >= 0)
      найден = повод.область === 'боковик'
        ? {область: 'боковик', строка: повод.строка + шаг * d, столбец: повод.столбец,
           значение: v, уровень: уровень, дети: кандидаты}
        : {область: 'шапка', строка: повод.строка, столбец: повод.столбец + шаг * d,
           значение: v, уровень: уровень, дети: кандидаты};
  }
  if(!найден){ панель.сообщение('Родителя «' + мой + '» на листе нет — он не раскрыт отсюда.'); return; }
  if(УбратьДетей(найден, найден.дети, п)){
    панель.сообщение('Свёрнут «' + найден.значение + '».');
    await Обновить();
  } else панель.сообщение('Родитель уже свёрнут.');
}

/* Раскрыть до листьев. Потолок обязателен: иерархия счетов бывает на
   десяток уровней, и «раскрыть всё» без него превращает отчёт в сотни
   тысяч строк. Вглубь идём по ПЕРВОМУ ребёнку — раскрывать каждого значило
   бы умножать запросы к серверу на ширину иерархии. */
const ПРЕДЕЛ_ГЛУБИНЫ = 6;
async function РаскрытьВсё(){
  const повод = книга.повод;
  if(!повод || (повод.область !== 'боковик' && повод.область !== 'шапка')){
    панель.сообщение('Раскрывать можно измерения — боковик или шапку.');
    return;
  }
  const п = г_(прочитатьОтчёт());
  let текущий = Object.assign({}, повод), шагов = 0;
  while(шагов < ПРЕДЕЛ_ГЛУБИНЫ){
    const дети = await ДетиЧлена(п, текущий.измерение, String(текущий.значение || ''));
    if(!дети.length) break;
    if(УбратьДетей(текущий, дети, п)) РаскрытьОдин(текущий, дети, п);   // уже было — переложим ровно
    else РаскрытьОдин(текущий, дети, п);
    шагов++;
    /* Первый ребёнок встал сразу за родителем — от него и идём дальше. */
    текущий = Object.assign({}, текущий, {значение: дети[0]});
    if(текущий.область === 'боковик') текущий.строка = текущий.строка + 1;
    else текущий.столбец = текущий.столбец + 1;
  }
  панель.сообщение(шагов >= ПРЕДЕЛ_ГЛУБИНЫ
    ? 'Раскрыто ' + шагов + ' уровней — дальше остановился, чтобы отчёт не разросся.'
    : 'Раскрыто уровней: ' + шагов + '.');
  await Обновить();
}

/* Провал в исходные строки — пункт меню НА ЧИСЛЕ. Точку просмотра клетки
   приложение собрало из обеих осей; нам остаётся её показать. Настоящий
   drill-through упирается в то, какой отчёт детализации заведён на сервере,
   и его имя должно приходить из настроек, а не быть зашитым. */
async function ЧтоЗаЧисло(){
  const повод = книга.повод;
  if(!повод) return;
  const части = [];
  for(const имя in (повод.точка || {})) части.push(имя + ' = ' + повод.точка[имя]);
  if(!части.length){ панель.сообщение('Для этой клетки точка просмотра не собралась.'); return; }
  панель.сообщение(повод.адрес + ': ' + части.join('; '));
  сообщить(повод.адрес, '=', повод.значение, '|', части.join('; '));
}

/* Дети члена. У Planning путь у разных версий свой, поэтому пробуем два и
   различаем «сервер ответил, детей нет» и «не ответил вовсе». */
async function ДетиЧлена(п, измерение, член){
  const базовый = адрес(п, '/applications/{app}/dimensions/') + encodeURIComponent(измерение);
  const пути = [
    базовый + '/members/' + encodeURIComponent(член) + '/children',
    базовый + '/members?parent=' + encodeURIComponent(член),
  ];
  let последняя = null, ответил = false;
  for(const u of пути){
    try {
      const d = await взять(п, u);
      ответил = true;
      const список = ((d && (d.items || d.members || d.children)) || [])
        .map(function(x){ return x.name || x.имя || x; })
        .filter(function(x){ return typeof x === 'string' && x && x !== член; });
      if(список.length) return список;
    } catch(e){ последняя = e; }
  }
  /* Пустой УСПЕШНЫЙ ответ — это «детей нет», а не «не вышло». */
  if(ответил) return [];
  throw new Error('Не удалось получить детей «' + член + '»: '
    + (последняя ? последняя.message : 'сервер не ответил ни по одному пути'));
}

function г_(g){ return g.р; }

/* Номер столбца в буквы: 1 -> A, 27 -> AA. */
function бук(n){
  let s = '';
  while(n > 0){ const o = (n - 1) % 26; s = String.fromCharCode(65 + o) + s; n = (n - 1 - o) / 26; }
  return s;
}
